fn bounded(tail: &[u8]) -> (usize, bool, String) {
                let raw_tail_bytes = tail.len();
                let mut body = format!("{:?}", String::from_utf8_lossy(&tail));
                let body_truncated = body.len() > 64 * 1024;
                if body_truncated {
                    let mut end = 64 * 1024;
                    while !body.is_char_boundary(end) {
                        end -= 1;
                    }
                    body.truncate(end);
                }

(raw_tail_bytes, body_truncated, body)
}
fn main() {
for (label, byte) in [("invalid_utf8", 255u8), ("debug_escape", 1u8)] {
let raw = vec![byte; 65536];
let expanded = format!("{:?}", String::from_utf8_lossy(&raw));
let (raw_len, truncated, body) = bounded(&raw);
assert_eq!(raw_len, 65536);
assert!(expanded.len() > 65536);
assert!(truncated);
assert!(body.len() <= 65536);
assert!(std::str::from_utf8(body.as_bytes()).is_ok());
println!("case={label} raw_bytes={raw_len} expanded_bytes={} body_bytes={} truncated={truncated}", expanded.len(), body.len());
}
}
